        return default
    prefix = key + "="
    for line in file.read_text(encoding="utf-8", errors="replace").splitlines():
        if line.startswith(prefix):
            return line[len(prefix) :]
    return default



def _binary_available(session_env: Path, key: str, binary: str) -> str:
